 \protected\def\sphinxstrong#1{\textbf{#1}}
-\protected\def\sphinxcode#1{\texttt{#1}}
+\protected\def\sphinxcode#1{\unskip\texttt{#1}\ignorespaces}
 \protected\def\sphinxbfcode#1{\textbf{\sphinxcode{#1}}}
